    this.refresh,
  });

  final String version;
  final String profile;
  final int pid;
  /// Unix milliseconds
  final int startedAt;
  final String socket;
  /// filled per request
  final List<String> projects;
  /// filled per request
  final List<String> pinned;
  /// filled per request
  final List<DaemonChild> children;
  /// filled per request
  final DaemonRefresh? refresh;

  factory DaemonInfo.fromJson(Map<String, dynamic> json) {
    return DaemonInfo(
      version: json['version'] as String,
      profile: json['profile'] as String,
      pid: (json['pid'] as num).toInt(),
      startedAt: (json['startedAt'] as num).toInt(),
      socket: json['socket'] as String,
      projects: _list(
        json['projects'],
        (value) => value as String,
      ),
      pinned: _list(
        json['pinned'],
        (value) => value as String,
      ),
      children: _list(
        json['children'],
        (value) => _object(value, DaemonChild.fromJson),
      ),
      refresh: _objectOrNull(
        json['refresh'],
        DaemonRefresh.fromJson,
      ),
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['version'] = version;
    json['profile'] = profile;
    json['pid'] = pid;
    json['startedAt'] = startedAt;
