    }
    if (packTruncated != null) {
      json['packTruncated'] = packTruncated;
    }
    if (packSections != null) {
      json['packSections'] = packSections;
    }
    if (packKnown != null) {
      json['packKnown'] = packKnown;
    }
    return json;
  }
}

