/// WireBand is the pinned band: todo progress with its stale signal, and the
/// running cards. It travels as a node with ID "band" that is deliberately
/// not in roots, so a transcript walk ignores it.
class WireBand {
  const WireBand({
    this.todos,
    required this.done,
