/// DeltaKind is the discriminator of a fleet-stream delta.
enum DeltaKind {
  deltaActivity('activity'),
  deltaMode('mode'),
  deltaTelemetry('telemetry'),
  deltaWatch('watch'),
  deltaRun('run'),
  deltaPending('pending'),
  deltaGate('gate'),
  deltaHold('hold'),
  deltaBudget('budget'),
  deltaProjectRemoved('project_removed'),
  deltaInbox('inbox'),
  unknown('unknown');

  const DeltaKind(this.wire);

  /// The wire text this value stands for.
  final String wire;

  /// The value [wire] names, or [unknown] when this build does not
  /// know it.
  static DeltaKind fromWire(String wire) {
    for (final value in values) {
      if (value != unknown && value.wire == wire) {
        return value;
      }
    }
    return unknown;
  }
}

/// FleetDelta is one entry on the fleet stream.
class FleetDelta {
  const FleetDelta({
    required this.kind,
    required this.sessionID,
    this.activity,
    this.access,
    this.contextPct,
    this.changedFiles,
    this.pendingKind,
    this.gate,
    this.agentID,
    this.run,
    this.watch,
    this.at,
    this.toolStats,
    this.rules,
    this.held,
    this.by,
    this.rawEnums = const {},
  });

  final DeltaKind kind;
  final String sessionID;
  final String? activity;
  final AccessState? access;
  final int? contextPct;
  final int? changedFiles;
  final PendingKind? pendingKind;
  final GateRecord? gate;
  final String? agentID;
  final Object? run;
  final Object? watch;
  final int? at;
  final Object? toolStats;
  final Object? rules;
  final bool? held;
  final String? by;

  /// The wire text of each enum field this build has no value
  /// for, keyed by JSON name, so a round trip keeps it.
  final Map<String, String> rawEnums;

  factory FleetDelta.fromJson(Map<String, dynamic> json) {
    final rawEnums = <String, String>{};
    final kindWire = json['kind'] as String;
    final kind = DeltaKind.fromWire(kindWire);
    if (kind == DeltaKind.unknown) {
      rawEnums['kind'] = kindWire;
    }
    final pendingKindWire = json['pendingKind'] as String?;
    final pendingKind = _enumOrNull(pendingKindWire, PendingKind.fromWire);
    if (pendingKind == PendingKind.unknown) {
      rawEnums['pendingKind'] = pendingKindWire!;
    }
    return FleetDelta(
      kind: kind,
      sessionID: json['sessionId'] as String,
      activity: json['activity'] as String?,
      access: _objectOrNull(
        json['access'],
        AccessState.fromJson,
      ),
      contextPct: (json['contextPct'] as num?)?.toInt(),
      changedFiles: (json['changedFiles'] as num?)?.toInt(),
      pendingKind: pendingKind,
      gate: _objectOrNull(
        json['gate'],
        GateRecord.fromJson,
      ),
      agentID: json['agentId'] as String?,
      run: json['run'],
      watch: json['event'],
      at: (json['at'] as num?)?.toInt(),
      toolStats: json['toolStats'],
      rules: json['rules'],
      held: json['held'] as bool?,
      by: json['by'] as String?,
      rawEnums: rawEnums,
    );
  }

  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['kind'] = rawEnums['kind'] ?? kind.wire;
    json['sessionId'] = sessionID;
    if (activity != null) {
      json['activity'] = activity;
    }
    if (access != null) {
      json['access'] = access!.toJson();
    }
    if (contextPct != null) {
      json['contextPct'] = contextPct;
    }
    if (changedFiles != null) {
      json['changedFiles'] = changedFiles;
    }
    if (pendingKind != null) {
      json['pendingKind'] = rawEnums['pendingKind'] ?? pendingKind!.wire;
    }
    if (gate != null) {
      json['gate'] = gate!.toJson();
    }
    if (agentID != null) {
      json['agentId'] = agentID;
    }
    if (run != null) {
      json['run'] = run;
    }
    if (watch != null) {
      json['event'] = watch;
    }
    if (at != null) {
      json['at'] = at;
    }
    if (toolStats != null) {
      json['toolStats'] = toolStats;
    }
    if (rules != null) {
      json['rules'] = rules;
    }
    if (held != null) {
      json['held'] = held;
    }
    if (by != null) {
      json['by'] = by;
    }
    return json;
  }
}

